import{_ as e,o as a,c as i,a3 as s}from"./chunks/framework.BkJHvlZ8.js";const k=JSON.parse('{"title":"API 约定","description":"","frontmatter":{},"headers":[],"relativePath":"guide/go/api.md","filePath":"guide/go/api.md","lastUpdated":1789529774000}'),d={name:"guide/go/api.md"};function o(r,t,n,h,l,p){return a(),i("div",null,[...t[0]||(t[0]=[s('<h1 id="api-约定" tabindex="-1">API 约定 <a class="header-anchor" href="#api-约定" aria-label="Permalink to &quot;API 约定&quot;">​</a></h1><h2 id="地址与响应" tabindex="-1">地址与响应 <a class="header-anchor" href="#地址与响应" aria-label="Permalink to &quot;地址与响应&quot;">​</a></h2><p>核心 API 前缀为 <code>/api/v1</code>。统一响应格式：</p><div class="language-json vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">json</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{ </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;code&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">0</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;msg&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;success&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;data&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: {} }</span></span></code></pre></div><p>业务错误使用 <code>401</code>（登录态无效）、<code>403</code>（权限不足）、<code>404</code>（资源不存在）、<code>409</code>（状态冲突）和 <code>422</code>（参数校验失败）。</p><h2 id="认证" tabindex="-1">认证 <a class="header-anchor" href="#认证" aria-label="Permalink to &quot;认证&quot;">​</a></h2><p>需要登录的请求携带：</p><div class="language-http vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">http</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">Authorization</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">:</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> Bearer &lt;access_token&gt;</span></span></code></pre></div><p>JWT 使用 HS256 算法，access 令牌有效期 24 小时，refresh 令牌 7 天。中间件 <code>jwt_auth</code> 校验令牌签名、有效期和黑名单状态；<code>permission</code> 中间件基于权限标识做 RBAC 鉴权。</p><p>改密后 <code>TokenVersion</code> 递增，旧令牌自动失效。</p><h2 id="核心接口分组" tabindex="-1">核心接口分组 <a class="header-anchor" href="#核心接口分组" aria-label="Permalink to &quot;核心接口分组&quot;">​</a></h2><table tabindex="0"><thead><tr><th>分组</th><th>作用</th></tr></thead><tbody><tr><td><code>/auth</code></td><td>登录、刷新令牌、当前用户信息</td></tr><tr><td><code>/users</code></td><td>用户管理</td></tr><tr><td><code>/roles</code></td><td>角色和菜单权限</td></tr><tr><td><code>/menus</code></td><td>菜单树和动态路由来源</td></tr><tr><td><code>/depts</code></td><td>部门和数据范围</td></tr><tr><td><code>/plugins</code></td><td>插件发现、热启停、上传和卸载</td></tr><tr><td><code>/mcp</code></td><td>工具、资源、提示词和审计</td></tr><tr><td><code>/ai</code></td><td>多模型对话和工具调用</td></tr></tbody></table><h2 id="编写插件-api" tabindex="-1">编写插件 API <a class="header-anchor" href="#编写插件-api" aria-label="Permalink to &quot;编写插件 API&quot;">​</a></h2><p>插件路由在插件的 <code>Register()</code> 方法中挂载到 Gin RouterGroup。使用 <code>internal/schema</code> 中的 DTO 做请求绑定，通过 <code>internal/pkg/response</code> 统一响应。</p><p>注意事项：</p><ul><li>不要在公开接口返回密钥、内部文件路径或未发布数据。</li><li>文件路径必须经过目录边界校验。</li><li>插件接口应使用自己的权限标识（如 <code>my_plugin:*</code>）。</li><li>MCP 工具需声明 <code>RequiredPermissions</code>，网关会自动做 RBAC 过滤。</li></ul>',16)])])}const u=e(d,[["render",o]]);export{k as __pageData,u as default};
